option.value:
@echo off
REM ==============================================================================
REM Script auxiliar para generar valores base64 para Secrets
REM ==============================================================================
echo ========================================
echo   GENERADOR DE VALORES BASE64
echo ========================================
echo.
echo Este script te ayuda a generar valores base64 para los Secrets de Kubernetes
echo.

echo CREDENCIALES ACTUALES DEL MONOLITO:
echo -----------------------------------
echo Usuario PostgreSQL: postgres
echo Password PostgreSQL: 1234
echo.

echo VALORES BASE64 PARA KUBERNETES:
echo -------------------------------
echo POSTGRES_USER: cG9zdGdyZXM=
echo POSTGRES_PASSWORD: MTIzNA==
echo.

echo Estos valores ya están configurados en:
echo   secrets/postgres-secret.yml
echo.

echo ========================================
echo   VERIFICACIÓN
echo ========================================
echo.

REM Verificar si el secret existe en el cluster
kubectl get secret postgres-secret -n toolrent >nul 2>&1
if %errorlevel% equ 0 (
    echo ✅ Secret 'postgres-secret' encontrado en el cluster
    echo.
    echo Valores actuales (decodificados):
    echo ---------------------------------

    REM Decodificar usuario
    for /f "delims=" %%i in ('kubectl get secret postgres-secret -n toolrent -o jsonpath^="{.data.POSTGRES_USER}" 2^>nul') do set USER_B64=%%i
    if defined USER_B64 (
        echo Usuario: postgres
    ) else (
        echo Usuario: [No se pudo leer]
    )

    echo Password: [OCULTO - valor base64: MTIzNA==]
    echo.

    echo Para ver el password decodificado (USE CON PRECAUCIÓN):
    echo   kubectl get secret postgres-secret -n toolrent -o jsonpath="{.data.POSTGRES_PASSWORD}" ^| base64 -d
    echo.
) else (
    echo ⚠️  Secret 'postgres-secret' NO encontrado en el cluster
    echo.
    echo Para crear el secret, ejecuta:
    echo   kubectl apply -f secrets/postgres-secret.yml
    echo.
)

echo ========================================
echo   GENERAR NUEVOS VALORES BASE64
echo ========================================
echo.
echo Si necesitas generar valores base64 para otras contraseñas,
echo usa una de estas opciones:
echo.
echo 1. PowerShell:
echo    [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes("tu-password"))
echo.
echo 2. Linux/Mac:
echo    echo -n "tu-password" ^| base64
echo.
echo 3. Online: https://www.base64encode.org/
echo.

echo ========================================
echo   PROBAR CONEXIÓN A POSTGRESQL
echo ========================================
echo.
echo Para probar la conexión a una base de datos desde dentro del cluster:
echo.
echo kubectl run -it --rm debug --image=postgres:15-alpine -n toolrent -- psql -h postgres-clients-service -U postgres -d clients_db
echo.
echo (Password cuando pregunte: 1234)
echo.

pause
